 path:[["Sept – oct. 2026","Premières sessions","Chevening, Rhodes, Commonwealth, Knight-Hennessy et GKS licence sont clos pour 2027. Notez-les pour 2028."],
  ["Nov. – déc. 2026","Pleine saison","Licence aux États-Unis (1er janv.) et doctorat (1er–15 déc.), DAAD, nominations Eiffel, HKPFS, SINGA, ETH/EPFL, Yenching, NYU Law, AAUW."],
  ["Janv. 2027","L'Europe s'ouvre","Erasmus Mundus, Gates et Clarendon, universités suédoises et finlandaises (15 janv.), Stipendium Hungaricum, BID, LSE et bourses d'entrée à Hong Kong."],
  ["Févr. – mars 2027","Asie et programmes publics","Türkiye Bursları (20 févr.), GKS master, CSC Chine, Pays-Bas, Irlande GOI-IES, Master Mind, Université panafricaine, Manaaki NZ."],
  ["Avr. – juin 2027","Résultats et rattrapages","Les offres arrivent. Session MEXT par ambassade (pour 2028), bourses de master en Australie, universités saoudiennes, bourses italiennes, appels mexicains et brésiliens."],
  ["Juin – août 2027","Diplôme et préparation","Remise des diplômes, relevés de notes, visas, bourses DSU italiennes (juil.–sept.). Préparez vos candidatures 2028 si besoin."],
  ["Août – oct. 2027","Ouverture des sessions 2028","Chevening, Rhodes, Commonwealth, Knight-Hennessy, GKS licence et sessions de recherche en Australie pour 2028."],
  ["Sept – oct. 2027","Rentrée","Commencez votre diplôme. En première année, demandez des bourses complémentaires dans votre université."]],
 tips:[["Partez de la date limite","Triez par date limite et remontez le temps. La plupart des bourses demandent 6 à 10 semaines pour réunir lettres, scores et traductions."],
  ["Vérifiez la moyenne officielle","Si un minimum est publié, vérifiez-le avec la conversion officielle. S'il s'agit d'une moyenne habituelle, un dossier solide peut quand même l'emporter."],
  ["Adaptez chaque lettre","Citez les cours, professeurs et laboratoires du programme. Expliquez ce que vous ferez ensuite et pourquoi c'est important pour votre pays."],
  ["Choisissez des référents qui vous connaissent","Un enseignant qui a encadré votre projet écrit une meilleure lettre qu'un nom célèbre. Demandez 6 semaines à l'avance et envoyez votre CV."],
  ["Passez le test d'anglais tôt","IELTS 7,0 ou TOEFL 100 suffit presque partout. Demandez aussi à votre université une attestation d'enseignement en anglais."],
  ["Contactez des professeurs","Pour les masters de recherche et doctorats (Chine, Japon, Corée, Canada, États-Unis, Singapour), l'intérêt d'un directeur décide souvent du financement."],
  ["Postulez largement","Visez 10 à 20 candidatures dans 3 à 5 pays : quelques rêves, beaucoup d'options réalistes et deux ou trois valeurs sûres."],
  ["Montrez votre impact, pas seulement vos notes","Leadership, bénévolat, concours, publications et expérience départagent les moyennes égales."],
  ["Ne payez jamais pour postuler","Les bourses publiques comme CSC, MEXT, GKS, Türkiye Bursları, DAAD et Erasmus Mundus sont gratuites. Méfiez-vous des agents qui promettent une bourse garantie."]]
